/****** Object:  View [dbo].[vw_SalesWithDetails]    Script Date: 4/5/2026 8:55:22 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO

CREATE VIEW [dbo].[vw_SalesWithDetails] AS
SELECT 
    s.SaleID,
    s.InvoiceNumber,
    s.CustomerID,
    c.CustomerName,
    s.SaleDate,
    s.SubTotal,
    s.DiscountAmount,
    s.DiscountPercent,
    s.TaxAmount,
    s.TaxPercent,
    s.TotalAmount,
    s.PaymentMethod,
    s.PaidAmount,
    s.ChangeAmount,
    s.UserID,
    u.FullName as UserName,
    s.Status,
    s.Notes,
    s.CreatedDate,
    s.LastModified,
    s.ModifiedBy,
    um.FullName as ModifiedByName
FROM Sales s
LEFT JOIN Customers c ON s.CustomerID = c.CustomerID
LEFT JOIN Users u ON s.UserID = u.UserID
LEFT JOIN Users um ON s.ModifiedBy = um.UserID

