/****** Object:  StoredProcedure [dbo].[sp_GetPreviousDayClosingBalance]    Script Date: 4/5/2026 8:55:23 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[sp_GetPreviousDayClosingBalance]
    @CurrentDate DATETIME
AS
BEGIN
    SET NOCOUNT ON;
    
    SELECT TOP 1 ClosingBalance 
    FROM DayClosings 
    WHERE CAST(ClosingDate AS DATE) < CAST(@CurrentDate AS DATE)
        AND Status = 'Closed'
    ORDER BY ClosingDate DESC
END

GO
/****** Object:  StoredProcedure [dbo].[sp_IsDayClosed]    Script Date: 4/5/2026 8:55:23 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[sp_IsDayClosed]
    @Date DATETIME
AS
BEGIN
    SET NOCOUNT ON;
    
    SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END AS IsClosed
    FROM DayClosings 
    WHERE CAST(ClosingDate AS DATE) = CAST(@Date AS DATE)
        AND Status = 'Closed'
END

