/****** Object:  StoredProcedure [dbo].[sp_UpdateSale]    Script Date: 4/5/2026 8:55:23 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[sp_UpdateSale]
    @SaleID INT,
    @CustomerID INT,
    @SaleDate DATETIME,
    @SubTotal DECIMAL(10,2),
    @DiscountAmount DECIMAL(10,2) = 0,
    @DiscountPercent DECIMAL(5,2) = 0,
    @TaxAmount DECIMAL(10,2),
    @TaxPercent DECIMAL(5,2),
    @TotalAmount DECIMAL(10,2),
    @PaymentMethod NVARCHAR(20),
    @PaidAmount DECIMAL(10,2),
    @ChangeAmount DECIMAL(10,2),
    @UserID INT,
    @Notes NVARCHAR(500) = NULL,
    @ModifiedBy INT
AS
BEGIN
    SET NOCOUNT ON;
    
    BEGIN TRY
        BEGIN TRANSACTION;
        
        -- Update the sale
        UPDATE Sales 
        SET CustomerID = @CustomerID,
            SaleDate = @SaleDate,
            SubTotal = @SubTotal,
            DiscountAmount = @DiscountAmount,
            DiscountPercent = @DiscountPercent,
            TaxAmount = @TaxAmount,
            TaxPercent = @TaxPercent,
            TotalAmount = @TotalAmount,
            PaymentMethod = @PaymentMethod,
            PaidAmount = @PaidAmount,
            ChangeAmount = @ChangeAmount,
            UserID = @UserID,
            Notes = @Notes,
            LastModified = GETDATE(),
            ModifiedBy = @ModifiedBy
        WHERE SaleID = @SaleID;
        
        -- Check if any rows were affected
        IF @@ROWCOUNT = 0
        BEGIN
            RAISERROR('Sale with ID %d not found', 16, 1, @SaleID);
        END
        
        COMMIT TRANSACTION;
        SELECT 1 as Success, 'Sale updated successfully' as Message;
        
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;
        SELECT 0 as Success, ERROR_MESSAGE() as Message;
    END CATCH
END

