    @SaleID INT,
    @SaleItems NVARCHAR(MAX) -- JSON string of sale items
AS
BEGIN
    SET NOCOUNT ON;
    
    BEGIN TRY
        BEGIN TRANSACTION;
        
        -- Delete existing sale items
        DELETE FROM SaleItems WHERE SaleID = @SaleID;
        
        -- Insert new sale items (this would need to be called from C# with proper JSON parsing)
