        COMMIT TRANSACTION;
        SELECT 1 as Success, 'Sale items updated successfully' as Message;
        
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;
        SELECT 0 as Success, ERROR_MESSAGE() as Message;
    END CATCH
END

